evidence_items.text:
def extract_json_block(raw):
    clean = re.sub(r'```(?:json)?\s*', '', raw.strip()).replace('```', '').strip()
    s, e = clean.find('{'), clean.rfind('}')
    if s < 0 or e < 0: raise ValueError("JSON 블록 없음")
    return clean[s:e+1]

